package com.yupi.template.runtime;
import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import com.yupi.template.service.*;import com.yupi.template.agent.agents.*;import com.yupi.template.modelconfig.*;import com.yupi.template.model.entity.Article;import org.springframework.test.util.ReflectionTestUtils;import java.util.Map;
class AdviceOnlyRetryTest {
 @Test void retryRunsReviewWithoutRegeneratingTextOrImages()throws Exception{var articles=mock(ArticleService.class);var a=new Article();a.setTaskId("t");a.setTopic("topic");a.setMainTitle("title");a.setContent("saved body");a.setEnabledImageMethods("[\"DEMO\"]");when(articles.getByTaskId("t")).thenReturn(a);var titles=mock(TitleGeneratorAgent.class);var outlines=mock(OutlineGeneratorAgent.class);var store=mock(QuickCreationStore.class);var media=mock(ArticleMediaProcessor.class);var model=mock(ManagedChatModel.class);var settings=mock(ModelSettings.class);var spec=new ModelSpec("id",1,"test","TEXT","compatible","https://example.com","m",60,2000,"2K","1:1");when(settings.taskText("t")).thenReturn(spec);when(settings.key(spec)).thenReturn("test-only");when(model.completeReview(eq(spec),anyString(),anyString(),eq(1800))).thenReturn(new ManagedChatModel.TextResult("{\"schemaVersion\":1,\"decision\":\"PASS\",\"issues\":[]}","req",Map.of()));var quick=new QuickCreation(titles,outlines,store,articles,media,model,settings);ReflectionTestUtils.setField(quick,"interventions",mock(ArticleInterventionService.class));quick.run(new RuntimeStore.Work(new RuntimeScope.Ticket("t","req","run",1),"QUICK_ADVICE_RETRY","Q_ADVICE","{}"));verify(model,times(1)).completeReview(eq(spec),anyString(),anyString(),eq(1800));verify(store).done(any(),any(),any(),isNull());verifyNoInteractions(titles,outlines,media);}
}
